local _KW_BATCH = 12
local _KW_URL_MAX = 6000

local function _kwIdentities()
    local ids, seen = {}, {}
    local function push(s)
        local low = s:lower()
        if s == "" or seen[s] or low == "none" or low == "unknown" or low == "unknown_hwid" or low == "nil" then return end
        seen[s] = true
        ids[#ids + 1] = s
    end
    local function add(v)
        if v == nil then return end
        local s = tostring(v)
        push(s:sub(1, 1024))
        if #s > 1024 then push((s:gsub("[^%w_%-%.]", "")):sub(1, 1024)) end
    end
    local uid
    pcall(function()
        local lp = game:GetService("Players").LocalPlayer
        if lp and lp.UserId and lp.UserId ~= 0 then uid = tostring(lp.UserId) end
    end)
    if uid then add("rbx-" .. uid) end
    pcall(function()
        local sdk = (type(getgenv) == "function" and getgenv().PandaAuthV4) or _G.PandaAuthV4
        if type(sdk) == "table" and type(sdk.GetIdentity) == "function" then add(sdk.GetIdentity()) end
    end)
    pcall(function() if type(gethwid) == "function" then add(gethwid()) end end)
    pcall(function() if type(getfingerprintid) == "function" then add(getfingerprintid()) end end)
    pcall(function() if type(getdeviceid) == "function" then add(getdeviceid()) end end)
    pcall(function()
        if type(readfile) == "function" and (type(isfile) ~= "function" or isfile(_KW_FILE)) then
            add(readfile(_KW_FILE))
        end
    end)
    pcall(function()
        local cid = tostring(game:GetService("RbxAnalyticsService"):GetClientId())
        add(cid)
        add((cid:gsub("-", "")))
    end)
